    [0, 1, 3, 6].forEach(function (d, j) { var t = d / 9, x = -160 + 220 * t, y = 115 - 111 * t; o.push({ f: "sphere", c: [x, y + 10, -30], r: 8, coul: "#B87333" }); o.push({ f: "boite", c: [x, y + 1, -25], d: [2, 6, 2], coul: "#C62828", div: false }); });
